// Package crawlerdefaults is the platform's default trusted crawler list
// (CC trusted_crawlers, FX47) and the dataset the license service builds
// from it every day: each crawler's official IP ranges fetched from its
// sources (JSON, CSV or plain text), at most 256 networks per crawler
// (aggregated beyond), delivered to control planes as the artifact
// dataset/trusted-crawlers.
//
// default.json is generated by scripts/security/datasets/gen_default_crawlers.py
// (cloudflare-* and monitor/webhook/tool crawlers are not defaults).
package crawlerdefaults

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"net/netip"
	"sort"
	"strings"

	"github.com/cdnca/cdnca/libs/edgeconfig"
)

const (
	DefaultsSchema = "cdnca.default-crawlers/v1"
	DatasetSchema  = "cdnca.trusted-crawlers/v1"
	// ArtifactID / MediaType name the dataset in the artifact catalog.
	ArtifactID = "dataset/trusted-crawlers"
	MediaType  = "application/vnd.cdnca.trusted-crawlers+json;version=1"
	// MaxNetworks is the CC trusted crawler networks limit.
	MaxNetworks = 256
	// MaxDatasetBytes bounds the dataset (32 crawlers x 256 networks).
	MaxDatasetBytes = 1 << 20
)

// Source formats.
const (
	FormatJSON = "json"
	FormatCSV  = "csv"
	FormatText = "text"
)

var ErrInvalid = errors.New("invalid trusted crawler data")

//go:embed default.json
var defaultJSON []byte

// Source is one official IP range list of a crawler. JSON: every string
// value that is an address or prefix (OnlyKey: only under that top-level
// key; WhereField/WhereValue: only objects whose field has that value).
// CSV: the first column of each line. Text: every whitespace separated
// token. Lines starting with '#' are comments in CSV and text.
type Source struct {
	URL        string `json:"url"`
	Format     string `json:"format"`
	OnlyKey    string `json:"only_key,omitempty"`
	WhereField string `json:"where_field,omitempty"`
	WhereValue string `json:"where_value,omitempty"`
}

// Crawler is one default list entry: the crawlers of one vendor merged
// (Members), verified by Networks / RDNSSuffixes and by the networks the
// Sources list.
type Crawler struct {
	Name            string   `json:"name"`
	Members         []string `json:"members"`
	Categories      []string `json:"categories"`
	UserAgentTokens []string `json:"user_agent_tokens"`
	Networks        []string `json:"networks,omitempty"`
	RDNSSuffixes    []string `json:"rdns_suffixes,omitempty"`
	Sources         []Source `json:"sources,omitempty"`
}

// Defaults is the embedded default list, sorted by name.
func Defaults() []Crawler {
	var document struct {
		Schema   string    `json:"schema"`
		Source   string    `json:"source"`
		Crawlers []Crawler `json:"crawlers"`
	}
	decoder := json.NewDecoder(bytes.NewReader(defaultJSON))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&document); err != nil || document.Schema != DefaultsSchema {
		panic(fmt.Sprintf("crawlerdefaults: embedded default.json: %v", err))
	}
	return document.Crawlers
}

// Dataset is the dataset/trusted-crawlers artifact: the default crawlers
// as CC trusted crawlers (canonical: sorted, networks fetched and merged),
// GeneratedAt (RFC 3339) when the license service built it.
type Dataset struct {
	Schema      string                          `json:"schema"`
	GeneratedAt string                          `json:"generated_at"`
	Crawlers    []edgeconfig.CCV2TrustedCrawler `json:"crawlers"`
}

// BuildDataset turns the defaults and their fetched networks (by crawler
// name) into the dataset. A crawler without any verification (no networks
// fetched yet and no rDNS suffixes) is left out: a User-Agent alone is
// never proof.
func BuildDataset(defaults []Crawler, fetched map[string][]netip.Prefix, generatedAt string) (Dataset, error) {
	dataset := Dataset{Schema: DatasetSchema, GeneratedAt: generatedAt, Crawlers: []edgeconfig.CCV2TrustedCrawler{}}
	for _, crawler := range defaults {
		var prefixes []netip.Prefix
		for _, network := range crawler.Networks {
			prefix, err := netip.ParsePrefix(network)
			if err != nil {
				return Dataset{}, fmt.Errorf("%w: crawler %s network %q", ErrInvalid, crawler.Name, network)
			}
			prefixes = append(prefixes, prefix)
		}
		networks, err := Aggregate(append(prefixes, fetched[crawler.Name]...), MaxNetworks)
		if err != nil {
			return Dataset{}, fmt.Errorf("crawler %s: %w", crawler.Name, err)
		}
		if len(networks) == 0 && len(crawler.RDNSSuffixes) == 0 {
			continue
		}
		entry := edgeconfig.CCV2TrustedCrawler{Name: crawler.Name, UserAgentTokens: sortedCopy(crawler.UserAgentTokens),
			RDNSSuffixes: sortedCopy(crawler.RDNSSuffixes)}
		if len(networks) != 0 {
			entry.Networks = networks
		}
		dataset.Crawlers = append(dataset.Crawlers, entry)
	}
	sort.Slice(dataset.Crawlers, func(i, j int) bool { return dataset.Crawlers[i].Name < dataset.Crawlers[j].Name })
	if err := validateDataset(dataset); err != nil {
		return Dataset{}, err
	}
	return dataset, nil
}

// EncodeDataset is the canonical bytes of a valid dataset.
func EncodeDataset(dataset Dataset) ([]byte, error) {
	if err := validateDataset(dataset); err != nil {
		return nil, err
	}
	encoded, err := json.Marshal(dataset)
	if err != nil || len(encoded) > MaxDatasetBytes {
		return nil, fmt.Errorf("%w: dataset size", ErrInvalid)
	}
	return encoded, nil
}

// DecodeDataset accepts only canonical dataset bytes.
func DecodeDataset(content []byte) (Dataset, error) {
	if len(content) > MaxDatasetBytes {
		return Dataset{}, fmt.Errorf("%w: dataset size", ErrInvalid)
	}
	var dataset Dataset
	decoder := json.NewDecoder(bytes.NewReader(content))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&dataset); err != nil {
		return Dataset{}, fmt.Errorf("%w: %v", ErrInvalid, err)
	}
	canonical, err := EncodeDataset(dataset)
	if err != nil {
		return Dataset{}, err
	}
	if !bytes.Equal(canonical, content) {
		return Dataset{}, fmt.Errorf("%w: dataset is not canonical", ErrInvalid)
	}
	return dataset, nil
}

// validateDataset: the crawler list a CC v2 policy accepts.
func validateDataset(dataset Dataset) error {
	if dataset.Schema != DatasetSchema || dataset.Crawlers == nil || len(dataset.Crawlers) > 32 {
		return fmt.Errorf("%w: dataset", ErrInvalid)
	}
	if len(dataset.Crawlers) == 0 {
		return nil
	}
	const id = "00000000-0000-4000-8000-000000000001"
	policy := edgeconfig.CCV2Policy{SchemaVersion: edgeconfig.CCV2SchemaVersion, TenantScopeID: id, SiteID: id,
		PolicyID: id, PolicyVersion: 1, BindingID: id, BindingRevision: 1, PublicationID: id, Enabled: true,
		TrustedProxies: []string{}, Allowlist: []string{}, Rules: []edgeconfig.CCV2Rule{}, TrustedCrawlers: dataset.Crawlers}
	if _, err := edgeconfig.CanonicalCCV2Policy(policy); err != nil {
		return fmt.Errorf("%w: crawlers: %v", ErrInvalid, err)
	}
	return nil
}

// Merge adds the dataset's networks to the crawlers named like a dataset
// crawler (the site's own tokens and rDNS suffixes stay), aggregated to
// MaxNetworks. Other crawlers are unchanged. The result is a new slice.
func Merge(crawlers []edgeconfig.CCV2TrustedCrawler, dataset *Dataset) ([]edgeconfig.CCV2TrustedCrawler, error) {
	if dataset == nil || len(crawlers) == 0 {
		return crawlers, nil
	}
	byName := make(map[string]edgeconfig.CCV2TrustedCrawler, len(dataset.Crawlers))
	for _, crawler := range dataset.Crawlers {
		byName[crawler.Name] = crawler
	}
	result := make([]edgeconfig.CCV2TrustedCrawler, len(crawlers))
	for index, crawler := range crawlers {
		result[index] = crawler
		official, ok := byName[crawler.Name]
		if !ok || len(official.Networks) == 0 {
			continue
		}
		var prefixes []netip.Prefix
		for _, network := range append(append([]string(nil), crawler.Networks...), official.Networks...) {
			prefix, err := netip.ParsePrefix(network)
			if err != nil {
				return nil, fmt.Errorf("%w: crawler %s network %q", ErrInvalid, crawler.Name, network)
			}
			prefixes = append(prefixes, prefix)
		}
		networks, err := Aggregate(prefixes, MaxNetworks)
		if err != nil {
			return nil, fmt.Errorf("crawler %s: %w", crawler.Name, err)
		}
		result[index].Networks = networks
	}
	return result, nil
}

func sortedCopy(values []string) []string {
	if len(values) == 0 {
		return nil
	}
	result := append([]string(nil), values...)
	sort.Strings(result)
	return result
}

// ParseSource extracts the addresses and prefixes of one fetched source.
func ParseSource(source Source, body []byte) ([]netip.Prefix, error) {
	var prefixes []netip.Prefix
	add := func(value string) {
		if prefix, ok := parseNetwork(strings.TrimSpace(value)); ok {
			prefixes = append(prefixes, prefix)
		}
	}
	switch source.Format {
	case FormatJSON:
		var document any
		decoder := json.NewDecoder(bytes.NewReader(body))
		decoder.UseNumber()
		if err := decoder.Decode(&document); err != nil {
			return nil, fmt.Errorf("%w: %s: %v", ErrInvalid, source.URL, err)
		}
		if source.OnlyKey != "" {
			object, _ := document.(map[string]any)
			document = object[source.OnlyKey]
		}
		walkJSON(document, source, add)
	case FormatCSV, FormatText:
		for _, line := range strings.Split(string(body), "\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			if source.Format == FormatCSV {
				first, _, _ := strings.Cut(line, ",")
				add(first)
				continue
			}
			for _, field := range strings.Fields(line) {
				add(field)
			}
		}
	default:
		return nil, fmt.Errorf("%w: %s: format %q", ErrInvalid, source.URL, source.Format)
	}
	if len(prefixes) == 0 {
		return nil, fmt.Errorf("%w: %s: no networks", ErrInvalid, source.URL)
	}
	return prefixes, nil
}

func walkJSON(value any, source Source, add func(string)) {
	switch typed := value.(type) {
	case string:
		add(typed)
	case []any:
		for _, item := range typed {
			walkJSON(item, source, add)
		}
	case map[string]any:
		if source.WhereField != "" {
			if field, ok := typed[source.WhereField]; ok {
				if field != source.WhereValue {
					return
				}
			}
		}
		keys := make([]string, 0, len(typed))
		for key := range typed {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			walkJSON(typed[key], source, add)
		}
	}
}

// parseNetwork: an address (a host prefix) or a prefix, masked; refuses
// /0 and special-purpose space a crawler never comes from.
func parseNetwork(value string) (netip.Prefix, bool) {
	var prefix netip.Prefix
	if strings.Contains(value, "/") {
		parsed, err := netip.ParsePrefix(value)
		if err != nil {
			return netip.Prefix{}, false
		}
		prefix = parsed.Masked()
	} else {
		address, err := netip.ParseAddr(value)
		if err != nil || address.Zone() != "" {
			return netip.Prefix{}, false
		}
		prefix = netip.PrefixFrom(address, address.BitLen())
	}
	address := prefix.Addr()
	if address.Is4In6() || prefix.Bits() == 0 || !address.IsGlobalUnicast() || address.IsPrivate() {
		return netip.Prefix{}, false
	}
	return prefix, true
}
